#!/usr/bin/env bash
# recipes/crate-wasm-bindgen-backend--0-2-90/build.sh -- stage the wasm-bindgen-backend 0.2.90 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/wasm-bindgen-backend-0.2.90"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"fcdc935b63408d58a32f8cc9738a0bffd8f05cc7c002086c6ef20b7312ad9dcd"}\n' > "${dest}/.cargo-checksum.json"
